'use strict'
const electron=require('electron'),{app}=electron,assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),http=require('node:http')
const {BrowserSessionService}=require('../../desktop/services/browser-session.cjs')
app.setPath('userData',fs.mkdtempSync(path.join(require('node:os').tmpdir(),'stable-viewport-')));app.commandLine.appendSwitch('force-device-scale-factor','1');app.disableHardwareAcceleration();app.on('window-all-closed',()=>{})
let service,server
async function main(){
  await app.whenReady()
  const html=`<!doctype html><style>body{margin:0}.desktop{display:block}.mobile{display:none}@media(max-width:500px){.desktop{display:none}.mobile{display:block}}</style><button onclick="this.textContent='Clicked'">Action</button><h1 class="desktop">Desktop</h1><h1 class="mobile">Mobile</h1><p>${'Long text '.repeat(1200)}</p><table><tr><td>KEEP TABLE</td></tr></table>`
  server=http.createServer((req,res)=>res.end(html));await new Promise(r=>server.listen(0,'127.0.0.1',r))
  const data=new Map();service=new BrowserSessionService({electron,store:{getSetting:k=>data.get(k),setSetting:(k,v)=>data.set(k,v)},getWindow:()=>null})
  let snap=await service.execute('test',{action:'open',url:`http://127.0.0.1:${server.address().port}`});const tab=service.get('test',snap.tabId)
  assert.match(snap.text,/Desktop/)
  const opened=await service.execute('test',{action:'open',tabId:tab.id,url:`http://127.0.0.1:${server.address().port}`,width:390,height:844})
  assert.deepEqual([opened.viewport.width,opened.viewport.height],[390,844],'open must apply explicit dimensions instead of silently ignoring them')
  assert.match(opened.text,/Mobile/);assert(!opened.text.includes('Desktop'))
  assert.equal((await service.execute('test',{action:'read'})).viewport.width,390,'open dimensions persist')
  snap=await service.execute('test',{action:'resize',width:390,height:844})
  assert.deepEqual([snap.viewport.width,snap.viewport.height],[390,844]);assert.match(snap.text,/Mobile/);assert(!snap.text.includes('Desktop'))
  const bounds=tab.view.getBounds()
  const shot=await service.execute('test',{action:'screenshot',width:1440,height:1000})
  assert.deepEqual(electron.nativeImage.createFromDataURL(shot.image).getSize(),{width:1440,height:1000});assert.deepEqual(tab.view.getBounds(),bounds)
  const audit=await service.execute('test',{action:'audit',width:1280,height:900});assert.equal(audit.viewport.width,1280);assert.deepEqual(tab.view.getBounds(),bounds)
  await tab.view.webContents.executeJavaScript(`(()=>{const host=document.createElement('div');host.id='wrap-fixtures';host.innerHTML='<button id="orphan" style="display:block;width:130px;padding:0;border:0;font:20px/24px sans-serif;word-break:break-all">会员专属活动日</button><button id="balanced" style="display:block;width:130px;padding:0;border:0;font:20px/24px sans-serif;word-break:break-all">会员专属活动</button><button id="hidden-orphan" style="display:none;width:130px">会员专属活动日</button><h2 id="vertical" style="writing-mode:vertical-rl">会员专属活动日</h2>';document.body.prepend(host)})()`)
  const typography=await service.execute('test',{action:'audit'})
  assert(typography.typography?.candidates.some(c=>c.id==='orphan'&&c.lineCharacters.at(-1)===1),'audit should report a CJK single-character final line')
  assert(!typography.typography.candidates.some(c=>['balanced','hidden-orphan','vertical'].includes(c.id)))
  const typographyShot=await service.execute('test',{action:'screenshot'})
  assert(typographyShot.captureLayout.typography.candidates.some(c=>c.id==='orphan'))
  await tab.view.webContents.executeJavaScript(`document.getElementById('orphan').style.width='150px'`)
  const repairedType=await service.execute('test',{action:'audit'})
  assert(!repairedType.typography.candidates.some(c=>c.id==='orphan'),'a repaired label must disappear from current observations')
  await tab.view.webContents.executeJavaScript(`document.getElementById('wrap-fixtures').remove()`)
  await tab.view.webContents.executeJavaScript(`(async()=>{const box=document.createElement('div');box.style='width:100px;height:200px;overflow:auto';const img=document.createElement('img');img.alt='geometry-fixture';img.style='display:block;width:100px;height:auto';img.src='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="100" height="50"></svg>');box.append(img);document.body.append(box);await img.decode()})()`)
  const measured=await service.execute('test',{action:'audit'})
  const geometry=measured.imageGeometry.find(i=>i.alt==='geometry-fixture')
  assert.equal(geometry.naturalHeight,50);assert.equal(geometry.rect.height,50);assert.equal(geometry.containers[0].spaceBelowImage,150)
  assert(measured.imageSpacing?.candidates.some(c=>c.label==='geometry-fixture'&&c.gap===150),'unused image scrollbox space should be an explicit review candidate')
  await tab.view.webContents.executeJavaScript('document.querySelector("img").style.height="430px";document.querySelector("img").parentElement.style.height="500px"')
  assert((await service.execute('test',{action:'audit'})).imageSpacing.candidates.some(c=>c.gap===70),'a visible 70px gap must not disappear from the review candidates')
  await tab.view.webContents.executeJavaScript('document.querySelector("img").style.height="auto";document.querySelector("img").parentElement.style.height="200px"')
  await tab.view.webContents.executeJavaScript('document.querySelector("img").scrollIntoView({block:"center"})')
  const contextualShot=await service.execute('test',{action:'screenshot',width:800,height:900})
  assert.deepEqual([contextualShot.viewport.width,contextualShot.viewport.height],[800,900])
  const shotGeometry=contextualShot.captureLayout.images.find(i=>i.alt==='geometry-fixture')
  assert.equal(shotGeometry.naturalHeight,50);assert.equal(shotGeometry.containers[0].spaceBelowImage,150)
  assert.equal(shotGeometry.containers[0].label,undefined,'screenshot geometry should not repeat ancestor body text')
  assert(contextualShot.captureLayout.imageSpacing?.candidates.some(c=>c.label==='geometry-fixture'))
  await tab.view.webContents.executeJavaScript(`document.querySelector('img').parentElement.style.height='50px'`)
  assert(!(await service.execute('test',{action:'audit'})).imageSpacing.candidates.some(c=>c.label==='geometry-fixture'))
  await tab.view.webContents.executeJavaScript(`(async()=>{const img=document.querySelector('img'),box=img.parentElement;box.style.height='200px';box.innerHTML+='文字图注';const hidden=box.cloneNode(true);hidden.style.opacity='0';hidden.firstElementChild.alt='invisible';hidden.lastChild.remove();document.body.append(hidden);const padding=box.cloneNode(true);padding.style='width:100px;height:auto;padding-bottom:150px;overflow:auto';padding.firstElementChild.alt='padded';padding.lastChild.remove();document.body.append(padding);await Promise.all([...document.images].map(i=>i.decode()))})()`)
  const negative=await service.execute('test',{action:'audit'})
  assert.equal(negative.imageSpacing.candidates.length,0,'captions, invisible containers and intentional padding are not unused space')
  const assets=(await service.execute('test',{action:'read'})).imageInventory
  assert.equal(assets.total,3);assert(assets.images.every(i=>i.loaded&&i.naturalWidth===100&&i.naturalHeight===50))
  assert(!JSON.stringify(assets).includes('data:image'),'inventory must not repeat embedded binary data')
  assert.equal(contextualShot.captureLayout.hiddenText,undefined,'capture context is bounded to visible image geometry')
  await tab.view.webContents.executeJavaScript('scrollTo(0,0)')
  snap=await service.execute('test',{action:'read'});assert.equal(snap.viewport.width,390);assert(snap.text.length>10000);assert(snap.tables.length)
  const compact=await service.execute('test',{action:'scroll',value:'0'});assert(compact.text.length<=2000);assert.equal(compact.tables,undefined);assert.equal(compact.textTruncated,true);assert.match(compact.limits,/read/)
  const full=await service.execute('test',{action:'scroll',value:'0',detail:'full'});assert(full.text.length>10000);assert(full.tables.length)
  const before=tab.view.getBounds()
  for(const width of [0,319,2561,390.5,'390',NaN])await assert.rejects(service.execute('test',{action:'resize',width}),/320/)
  assert.deepEqual(tab.view.getBounds(),before)
  const evaluate=service.evaluate;service.evaluate=async()=>{throw Error('test audit failure')}
  const withoutLayout=await service.execute('test',{action:'screenshot',width:800})
  assert(withoutLayout.image.startsWith('data:image/png;base64,'))
  assert.match(withoutLayout.captureLayoutError,/test audit failure/);assert.deepEqual(tab.view.getBounds(),before)
  await assert.rejects(service.execute('test',{action:'audit',width:800}),/test audit failure/);assert.deepEqual(tab.view.getBounds(),before);service.evaluate=evaluate
  const abort=new AbortController();setTimeout(()=>abort.abort(),50)
  await assert.rejects(service.execute('test',{action:'screenshot',width:800},abort.signal));await new Promise(r=>setTimeout(r,350));assert.deepEqual(tab.view.getBounds(),before)
  service.control('test',tab.id,false);snap=await service.execute('test',{action:'read'});assert(snap.controls.length)
  const sdk={tool:(name,description,shape,handler)=>({name,handler}),createSdkMcpServer:v=>v}
  const tools=require('../../desktop/services/claude-tools.cjs').createClaudeTools({sdk,workspace:app.getPath('userData'),
    requestApproval:async()=>true,builtinTools:{execute:r=>service.execute('test',r.args),cancel(){}}})
  const browser=tools.tools.find(t=>t.name==='stable_browser').handler
  await browser({action:'read',tabId:tab.id})
  const batch=await browser({action:'batch',tabId:tab.id,steps:[
    {action:'resize',width:390,height:844},{action:'click',label:'Action'},
    {action:'screenshot',purpose:'mobile button'},{action:'resize',width:1440,height:1000},
    {action:'screenshot',purpose:'desktop button'},{action:'audit'},
  ]})
  assert.equal(batch.isError,undefined,JSON.stringify(batch.content.filter(p=>p.type==='text')))
  const images=batch.content.filter(p=>p.type==='image').map(p=>electron.nativeImage.createFromBuffer(Buffer.from(p.data,'base64')).getSize())
  assert.deepEqual(images,[{width:390,height:844},{width:1440,height:1000}])
  assert.equal(await tab.view.webContents.executeJavaScript('document.querySelector("button").textContent'),'Clicked')
  service.control('test',tab.id,true);await assert.rejects(service.execute('test',{action:'resize',width:800}),/接管/)
  assert.equal(electron.BrowserWindow.getAllWindows().length,0,'temporary compositor hosts must be cleaned up')
  console.log('VIEWPORT_PASSED')
}
main().then(()=>{service?.dispose();server?.close();app.exit(0)}).catch(e=>{console.error(e.stack);service?.dispose();server?.close();app.exit(1)})
